using System.Text.Json;
using System.Text.RegularExpressions;
using ONEXTweaks.WidgetBridge;

var checks=new List<string>();
void Check(bool ok,string name){if(!ok)throw new InvalidOperationException(name);checks.Add(name);}
string Plain(string markup)=>Regex.Replace(markup,"<[^>]+>","");
var example=OverlayFormatting.Example();
for(int level=1;level<=4;level++)Check(OverlayFormatting.Build(level,OverlayFormatting.Parse(OverlayFormatting.EditorDefaults()),example)==OverlayFormatting.Build(level,new Dictionary<string,string>(),example),"Editor defaults match native level "+level);
var native=OverlayFormatting.Preview(3,"",3,12,"0080FF");Check(native.NativeFontHeight==12&&native.NativeBaseColor=="0080FF","Native font height and reset color are retained");
Check(OverlayFormatting.Build(0,new Dictionary<string,string>(),example)==("",false),"Off releases text and graph");
var basic=OverlayFormatting.Preview(1,"");
Check(Plain(basic.ResolvedMarkup)=="60 FPS  16.7 ms   BAT 80% AC   18:42","Basic preview expands the same renderer macros");
Check(basic.Markup==OverlayFormatting.Build(1,OverlayFormatting.Parse(""),example).Text,"Preview uses the real renderer formatter");
Check(!basic.Graph&&basic.ExampleData&&!basic.CustomTagsPresent,"Preview explicitly identifies example values");
var horizontal=OverlayFormatting.Preview(2,"");
Check(Plain(horizontal.ResolvedMarkup).Contains("CPU 28%  55 C"),"Horizontal preset includes CPU metrics");
var vertical=OverlayFormatting.Preview(4,"L4:CPU,Battery,Blank5;L4_Order:Battery,Blank5,CPU;L4_Columns:1");
Check(Plain(vertical.ResolvedMarkup)=="BAT 80% AC\n\nCPU 28%  55 C","Vertical order and intentional blank rows");
var rows=OverlayFormatting.Preview(3,"L3:CPU,Battery,Blank1;L3_Order:Battery,Blank1,CPU");
Check(Plain(rows.ResolvedMarkup)=="BAT 80% AC\nCPU 28%  55 C","Horizontal explicit row break");
var ordered=OverlayFormatting.Preview(3,"L3:CPU,Battery;L3_Order:Battery,CPU,CPU");
Check(Regex.Matches(Plain(ordered.ResolvedMarkup),"CPU").Count==1,"Repeated order entries do not duplicate metrics");
var colors=OverlayFormatting.Preview(3,"L3:CPU;L3_Order:CPU;TextColor:FF0000;LabelColor:FFFFFF;Opacity:50");
Check(colors.Markup.Contains("<C=808080>CPU<C>")&&colors.Markup.Contains("<C=800000>28%"),"Text brightness affects real label/value RGB separately");
Check(OverlayFormatting.Preview(3,"L3:CPU;L3_CPU_Color:00FF00").Markup.Contains("<C=00FF00>CPU<C>"),"Per-metric label color");
var graph=OverlayFormatting.Preview(4,"L4:FrametimeGraph;L4_Order:FrametimeGraph");
Check(graph.Graph&&graph.Markup.Contains("<OBJ=00000000>")&&graph.GraphMs.Count>1,"Graph preview follows the real object marker");
var style=OverlayFormatting.Preview(3,"Font:Unispace|700;TextSize:200;Opacity:70;Background:1|75",3);
Check(style.FontFace=="Unispace"&&style.FontWeight==700&&style.TextSize==200&&style.TextBrightness==70&&style.BackgroundEnabled&&style.BackgroundOpacity==75&&style.NativeZoomRatio==3,"Effective font, scale, brightness, fill and native zoom metadata");
Check(OverlayFormatting.Preview(3,"TextSize:999;Opacity:0;Background:1|500",99) is {TextSize:300,TextBrightness:10,BackgroundOpacity:100,NativeZoomRatio:8},"Preview uses renderer bounds");
var custom=OverlayFormatting.Preview(3,"L3:;L3_Custom:<C=ABCDEF>Custom text<C>");
Check(custom.CustomTagsPresent&&custom.Markup.Contains("<C=ABCDEF>Custom text<C>"),"Advanced tags retained for explicit support warning");
Check(Plain(OverlayFormatting.Preview(3,"L3:").ResolvedMarkup)=="","Empty selection stays empty");
bool rejected=false;try{OverlayFormatting.Preview(0,"");}catch(InvalidDataException){rejected=true;}Check(rejected,"Invalid preview mode rejected");
rejected=false;try{OverlayFormatting.Preview(3,"L3_Custom:"+new string('x',2001));}catch(InvalidDataException){rejected=true;}Check(rejected,"Oversized custom markup rejected before rendering");
rejected=false;try{OverlayFormatting.Preview(3,"Font:"+new string('x',81));}catch(InvalidDataException){rejected=true;}Check(rejected,"Invalid font rejected without profile IO");
var missing=OverlayFormatting.Build(4,OverlayFormatting.Parse("L4:CPU,GPU,Memory,CPUCores,FpsStats;L4_Order:CPU,GPU,Memory,CPUCores,FpsStats"),new OverlayValues{Clock=example.Clock});
Check(missing.Text.Contains("--")&&!missing.Text.Contains("NaN"),"Unavailable sensors stay unavailable");
var json=JsonSerializer.Serialize(new{passed=true,tests=checks.Count,pureModelOnly=true,hardwareTested=false,checks},new JsonSerializerOptions{WriteIndented=true});
if(args.Length>0)File.WriteAllText(args[0],json+Environment.NewLine);
Console.WriteLine(json);
